<?php $base=$type==='category'?'categories':'tags'; ?><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Add <?= e($type) ?></h2><p>Organize posts for navigation and discovery.</p></div></div><form method="post" action="/admin/<?= e($base) ?>"><?= csrf_field() ?><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Slug</label><input name="slug" placeholder="auto-generated"></div><div class="field"><label>Description</label><textarea class="short" name="description"></textarea></div><button class="btn primary" type="submit">Add <?= e($type) ?></button></form></section><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Slug</th><th>Used</th><th></th></tr></thead><tbody><?php foreach($items as $t):?><tr><td><strong><?= e($t['name']) ?></strong></td><td class="code"><?= e($t['slug']) ?></td><td><?= (int)$t['usage_count'] ?></td><td><form method="post" action="/admin/<?= e($base) ?>/<?= (int)$t['id'] ?>/delete" data-confirm="Delete this <?= e($type) ?>?"><?= csrf_field() ?><button class="btn small danger" type="submit">Delete</button></form></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="4" class="empty-cell">No <?= e($base) ?> yet.</td></tr><?php endif;?></tbody></table></div></section></div>